import os
import time
import inotify

class FileMonitor:
    def __init__(self, path='./log'):
        self.path = path
        self.files = set()
        self.inotify = inotify.Inotify()

    def start(self):
        self.inotify.init()
        self.inotify.add_watch(self.path, inotify.WATCH_ALL)

        while True:
            events = self.inotify.poll()
            for event in events:
                if event.mask & inotify.IN_DELETE:
                    self.files.discard(event.name)
                elif event.mask & inotify.IN_MODIFY:
                    self.files.add(event.name)

    def stop(self):
        self.inotify.rm_watch(self.path)
